package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.widget.*;
import org.json.JSONObject;
final class TitleDetailsDialog {
 interface Change {void done(JSONObject item,boolean deleted);}
 static void show(Context c,JSONObject item,boolean media,Change changed){NativeSheet sheet=new NativeSheet(c,media?"Detalhes do título":"Detalhes do jogo");LinearLayout body=sheet.body;ImageView art=new ImageView(c);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(AppStyle.shape(art,0xff241b32,16));art.setClipToOutline(true);body.addView(art,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,190)));AccountImageLoader.load(art,value(item,"capa",""),media?"":value(item,"steam_appid",""));TextView title=NativeSheet.text(c,value(item,"nome","Sem título"),25,0xfff3f4f8);title.setTypeface(null,Typeface.BOLD);body.addView(title);TextView status=NativeSheet.text(c,value(item,"status","Sem status"),14,0xffc6b8ff);status.setPadding(NativeSheet.dp(c,14),NativeSheet.dp(c,10),NativeSheet.dp(c,14),NativeSheet.dp(c,10));status.setBackground(AppStyle.shape(status,0xff342b4d,12));body.addView(status);row(c,body,media?"Tipo":"Plataforma",value(item,media?"tipo":"plataforma","—"));row(c,body,media?"Onde assistir":"Horas jogadas",value(item,media?"onde":"horas","—")+(media?"":" h"));if(media)row(c,body,"Duração",value(item,"duracao","—"));row(c,body,"Sua avaliação",value(item,"nota","Ainda não avaliado"));if(!media){row(c,body,"Loja",value(item,"loja","—"));row(c,body,"Lançamento",value(item,"ano","—"));row(c,body,"Prioridade",value(item,"prioridade","—"));row(c,body,"Tempo para zerar",value(item,"tempo_est","—"));row(c,body,"Conquistas",value(item,"conquistas","—")+"%");if(!item.optBoolean("_readonly"))row(c,body,"Preço pago",item.isNull("preco")?"—":"R$ "+value(item,"preco","—"));}Object genres=item.opt("generos");if(genres!=null&&genres!=org.json.JSONObject.NULL)body.addView(NativeSheet.text(c,"Gêneros • "+genres.toString().replace("[","").replace("]","").replace("\"",""),13,0xffc4b6da));body.addView(NativeSheet.text(c,"SOBRE O TÍTULO",11,0xffa99bc7));TextView description=NativeSheet.text(c,"Buscando descrição no catálogo…",14,0xffc4ccd8);description.setTextIsSelectable(true);body.addView(description);new AccountRepository(c).catalogDescription(item,media,(rows,error)->{if(!sheet.dialog.isShowing())return;if(error!=null){description.setText("Descrição indisponível no momento.");return;}JSONObject detail=rows.optJSONObject(0);String synopsis=detail==null?"":detail.optString(media?"overview":"description_raw");DescriptionCredits.show(description,synopsis.isEmpty()?"Sem descrição disponível no catálogo.":synopsis);});String review=value(item,"review","");if(!review.isEmpty()){body.addView(NativeSheet.text(c,"SUAS ANOTAÇÕES",11,0xffa99bc7));TextView notes=NativeSheet.text(c,review,14,0xffc4ccd8);notes.setTextIsSelectable(true);body.addView(notes);}Button edit=new Button(c);edit.setText("Editar informações");AppStyle.button(edit,true);Button remove=new Button(c);remove.setText("Excluir da biblioteca");AppStyle.button(remove,false);remove.setTextColor(0xffffa8b5);boolean writable=!item.optBoolean("_readonly")&&ItemEditInput.validId(item.optString("id",""))&&item.has("updated_at");if(writable){if(media&&!LibraryCategory.classify(item.optString("tipo")).equals("filme")){Button progress=new Button(c);progress.setText("Progresso de episódios");AppStyle.button(progress,false);body.addView(progress);progress.setOnClickListener(v->JourneySheet.progress(c,item.optString("id")));}Button list=new Button(c);list.setText("Guardar em lista");AppStyle.button(list,false);body.addView(list);list.setOnClickListener(v->CollectionSheet.add(c,item.optString("id")));Button recommend=new Button(c);recommend.setText("Indicar a um amigo");AppStyle.button(recommend,false);body.addView(recommend);recommend.setOnClickListener(v->CollectionSheet.recommend(c,item.optString("id")));}edit.setEnabled(writable);remove.setEnabled(writable);if(!item.optBoolean("_readonly")){body.addView(edit);body.addView(remove);}edit.setOnClickListener(v->{sheet.busy(true);new ItemEditorDialog(c,item,media,(updated,deleted)->{sheet.dialog.dismiss();changed.done(updated,false);},()->sheet.busy(false));});remove.setOnClickListener(v->confirmDelete(c,item,media,sheet,changed));sheet.show();}
 private static void confirmDelete(Context c,JSONObject item,boolean media,NativeSheet parent,Change changed){NativeSheet confirm=new NativeSheet(c,"Excluir da biblioteca?");parent.busy(true);confirm.dialog.setOnDismissListener(d->parent.busy(false));confirm.body.addView(NativeSheet.text(c,value(item,"nome","Título"),22,0xfff3f4f8));confirm.body.addView(NativeSheet.text(c,"Este título será removido da sua biblioteca no app e no site. Não há lixeira no app. Isso não remove o jogo da sua conta Steam.",14,0xffbfc8d5));TextView state=NativeSheet.text(c,"",13,0xffffa8b5);confirm.body.addView(state);Button cancel=new Button(c);cancel.setText("Manter na biblioteca");AppStyle.button(cancel,false);cancel.setOnClickListener(v->confirm.dialog.dismiss());confirm.body.addView(cancel);Button erase=new Button(c);erase.setText("Confirmar exclusão");AppStyle.button(erase,true);erase.setBackground(AppStyle.shape(erase,0xff833f58,14));confirm.body.addView(erase);erase.setOnClickListener(v->{confirm.busy(true);erase.setEnabled(false);cancel.setEnabled(false);state.setText("Excluindo…");new AccountRepository(c).deleteItem(item.optString("id",""),media,item.isNull("updated_at")?null:item.optString("updated_at",""),(rows,error)->{confirm.busy(false);if(!confirm.dialog.isShowing())return;if(error!=null){state.setText(error+" Feche e confira a biblioteca antes de tentar novamente.");cancel.setEnabled(true);return;}confirm.dialog.dismiss();parent.dialog.dismiss();android.widget.Toast.makeText(c,"Título removido da biblioteca",android.widget.Toast.LENGTH_SHORT).show();changed.done(item,true);});});confirm.show();}
 private static void row(Context c,LinearLayout parent,String label,String value){LinearLayout tile=new LinearLayout(c);tile.setOrientation(LinearLayout.VERTICAL);tile.setPadding(NativeSheet.dp(c,14),NativeSheet.dp(c,8),NativeSheet.dp(c,14),NativeSheet.dp(c,8));tile.setBackground(AppStyle.shape(tile,0xff201b2b,18));LinearLayout grid=parent.getTag() instanceof LinearLayout?(LinearLayout)parent.getTag():null;if(grid==null||grid.getChildCount()==2){grid=new LinearLayout(c);parent.addView(grid);parent.setTag(grid);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,NativeSheet.dp(c,10),NativeSheet.dp(c,6),0);grid.addView(tile,lp);tile.addView(NativeSheet.text(c,label.toUpperCase(java.util.Locale.ROOT),10,0xff9ca9b8));tile.addView(NativeSheet.text(c,value,16,0xfff3f4f8));}
 private static String value(JSONObject item,String key,String fallback){String value=item.isNull(key)?fallback:item.optString(key,fallback);return value.trim().isEmpty()?fallback:value;}
}
